C1 = [
 L("Rethinking the 'Lungs of the Earth'", "重新思考「地球之肺」", [
   "Tropical rainforests occupy a modest share of the planet's land surface, yet they harbor more than half of its terrestrial species. The Amazon alone sprawls across nine countries and contains a staggering variety of life, much of it still undocumented.",
   "The popular label 'lungs of the Earth' is evocative but scientifically shaky. A mature forest does generate vast quantities of oxygen through photosynthesis, but its own organisms consume nearly all of it, so its net contribution to the air we breathe is close to zero.",
   "The forest's true planetary value lies elsewhere: in the enormous stores of carbon locked in its trees and soils, and in the moisture it recycles into rainfall across entire continents.",
   "That is why deforestation is so consequential. Clearing land for cattle pasture, soy and palm oil not only destroys habitats but also releases stored carbon, turning a buffer against climate change into a contributor to it. Some researchers warn that beyond a certain threshold, parts of the Amazon could degrade into drier savanna."],
  [w("harbor","verb","/ˈhɑːr.bɚ/","庇護、容納","to contain or provide a home for something","The lake harbors rare fish.","harbor species 孕育物種。"),
   w("sprawl","verb","/sprɑːl/","蔓延","to spread over a large area","The city sprawls for miles.","sprawl across… 橫跨…。"),
   w("staggering","adjective","/ˈstæɡ.ɚ.ɪŋ/","驚人的","extremely large or surprising","a staggering amount","a staggering variety 驚人的多樣性。"),
   w("evocative","adjective","/ɪˈvɑː.kə.t̬ɪv/","引起聯想的","bringing strong images or feelings to mind","an evocative name","evocative but… 生動但…。"),
   w("shaky","adjective","/ˈʃeɪ.ki/","不可靠的","not certain or not well supported","shaky evidence","scientifically shaky 科學上站不住腳。"),
   w("consequential","adjective","/ˌkɑːn.səˈkwen.ʃəl/","影響重大的","important and having serious results","a consequential decision","so consequential 如此重大。"),
   w("buffer","noun","/ˈbʌf.ɚ/","緩衝","something that reduces a harmful effect","a buffer against inflation","a buffer against… 對…的緩衝。"),
   w("threshold","noun","/ˈθreʃ.hoʊld/","門檻、臨界點","the level at which something starts to happen","a pain threshold","beyond a threshold 超過臨界點。")],
  [gr("強調助動詞 does generate","承認某事實再轉折。","A mature forest does generate vast quantities of oxygen"),
   gr("lie in","在於…。","The forest's true planetary value lies elsewhere"),
   gr("not only… but also…","不但…而且…。","not only destroys habitats but also releases stored carbon")],
  [q("Why does the writer call the 'lungs' label scientifically shaky?","The forest consumes almost all the oxygen it makes","Rainforests produce no oxygen","Lungs store carbon"),
   q("Where does the forest's true value lie, according to the text?","Carbon storage and recycling moisture into rain","Producing timber","Tourism"),
   q("What risk do some researchers warn about?","Parts of the Amazon turning into drier savanna","The Amazon growing too fast","More rain in deserts")]),
 L("What Science Says About Learning a Language as an Adult", "科學怎麼看成年人學語言", [
   "The belief that adults are hopeless language learners is remarkably persistent, and only partly justified. Children who are immersed early do tend to achieve a more native-like accent, but in controlled comparisons adults often progress faster in the initial stages, drawing on mature reasoning and better study habits.",
   "A highly influential idea in the field holds that acquisition is driven by comprehensible input: language we can mostly understand, pitched slightly beyond our current level. Exposure of this kind lets learners absorb grammar implicitly, as patterns rather than memorized rules.",
   "Consistency, meanwhile, tends to outperform intensity. Spaced review, in which words resurface at gradually lengthening intervals, exploits the way memory consolidates over time.",
   "Genuine interaction forces us to retrieve and adapt what we know under pressure. Perhaps the most decisive factor, though, is motivation. Learners who tie the language to a meaningful personal goal, whether a career, a relationship or a love of the culture, are far more likely to persevere through the inevitable plateaus."],
  [w("persistent","adjective","/pɚˈsɪs.tənt/","持久不散的","continuing for a long time","a persistent cough","remarkably persistent 非常根深蒂固。"),
   w("immerse","verb","/ɪˈmɝːs/","使沉浸","to put someone completely in an environment or activity","immerse yourself in English","be immersed 沉浸其中。"),
   w("comprehensible","adjective","/ˌkɑːm.prəˈhen.sə.bəl/","可理解的","able to be understood","comprehensible instructions","comprehensible input 可理解輸入。"),
   w("implicitly","adverb","/ɪmˈplɪs.ɪt.li/","隱性地、不明說地","without being directly expressed","learn implicitly","相對於 explicitly。"),
   w("outperform","verb","/ˌaʊt.pɚˈfɔːrm/","勝過","to do better than","outperform rivals","outperform intensity 勝過高強度。"),
   w("exploit","verb","/ɪkˈsplɔɪt/","利用","to use something to get an advantage","exploit an opportunity","exploit the way… 善用…的方式。"),
   w("persevere","verb","/ˌpɝː.səˈvɪr/","堅持不懈","to continue trying despite difficulty","persevere with your studies","persevere through… 熬過…。"),
   w("plateau","noun","/plæˈtoʊ/","停滯期","a period when progress stops","hit a plateau","the inevitable plateaus 必然的停滯期。")],
  [gr("分詞構句 drawing on…","說明方式：靠著…。","drawing on mature reasoning and better study habits"),
   gr("in which 引導關係子句","in which = 在這種複習中。","Spaced review, in which words resurface at gradually lengthening intervals"),
   gr("whether A, B or C","不論是 A、B 或 C（舉例）。","whether a career, a relationship or a love of the culture")],
  [q("What does the writer say about the belief that adults are poor learners?","It is only partly true","It is completely true","It was proven by children"),
   q("What is comprehensible input?","Language we mostly understand, slightly above our level","Very easy language we already know","Grammar rules to memorize"),
   q("What helps learners get through plateaus?","Strong personal motivation","Studying only grammar","Avoiding real conversations")]),
 L("Anatomy of a Typhoon", "颱風的構造", [
   "A typhoon is a mature tropical cyclone, a vast rotating system that can span hundreds of kilometers. The phenomenon is identical to an Atlantic hurricane; only the name changes with geography, and in the northwest Pacific, including the waters around Taiwan, 'typhoon' is the convention.",
   "These storms are essentially heat engines. They typically require sea-surface temperatures of at least 26 degrees Celsius. As moist air ascends and condenses into towering clouds, it releases latent heat, which lowers surface pressure and draws in yet more air, sustaining a self-reinforcing cycle.",
   "At the core lies the eye, an eerily tranquil zone of sinking air ringed by the eyewall, where winds are at their most ferocious.",
   "For Taiwan, the gravest hazards are often not the winds themselves but the water. Torrential rain on steep, saturated slopes can trigger landslides and flash floods, while storm surges inundate low-lying coasts. That is why heeding official warnings, and evacuating vulnerable areas early, saves lives."],
  [w("rotating","adjective","/ˈroʊ.teɪ.t̬ɪŋ/","旋轉的","turning around a central point","a rotating fan","rotate 的現在分詞當形容詞。"),
   w("convention","noun","/kənˈven.ʃən/","慣例","the usual way of doing something","by convention","is the convention 是慣用名稱。"),
   w("ascend","verb","/əˈsend/","上升","to move up","The plane ascended.","moist air ascends 濕空氣上升。"),
   w("latent","adjective","/ˈleɪ.tənt/","潛在的","present but not yet visible","latent heat","latent heat 潛熱。"),
   w("eerily","adverb","/ˈɪr.əl.i/","詭異地","in a strange and frightening way","eerily quiet","eerily tranquil 出奇地平靜。"),
   w("ferocious","adjective","/fəˈroʊ.ʃəs/","猛烈的","very violent or strong","a ferocious storm","at their most ferocious 最猛烈。"),
   w("torrential","adjective","/tɔːˈren.ʃəl/","傾盆的","falling heavily and fast","torrential rain","torrential rain 豪雨。"),
   w("inundate","verb","/ˈɪn.ʌn.deɪt/","淹沒","to flood an area with water","The river inundated the town.","inundate coasts 淹沒海岸。")],
  [gr("倒裝 At the core lies…","地點副詞片語放句首，動詞置於主詞前。","At the core lies the eye"),
   gr("分詞構句 sustaining…","表示結果：因而維持…。","sustaining a self-reinforcing cycle"),
   gr("not A but B","最大危險不是 A 而是 B。","the gravest hazards are often not the winds themselves but the water")],
  [q("How does a typhoon differ from a hurricane?","Only in name, depending on location","Typhoons are always weaker","Hurricanes have no eye"),
   q("Why is the storm described as a 'heat engine'?","Released heat keeps powering the storm","It needs cold water","It burns fuel"),
   q("What does the writer see as Taiwan's gravest typhoon hazard?","Water from rain and storm surges","Lightning","Cold temperatures")]),
 L("Why We Procrastinate, and What Is Really at Stake", "我們為什麼拖延，以及真正的代價", [
   "Tim Urban, the writer behind the blog Wait But Why, opens his TED talk with a sheepish confession: as a student, he postponed a 90-page thesis until the final 72 hours and then produced it in a frenzy of all-nighters.",
   "His comic model of the procrastinator's mind has since become famous. A sensible Rational Decision-Maker nominally steers, but an Instant Gratification Monkey repeatedly commandeers the controls in favor of whatever is easy and enjoyable. Order is restored only when the Panic Monster awakens, as a deadline looms.",
   "Beneath the humor lies a more sobering point. Deadlines at least summon the monster; the truly corrosive procrastination concerns goals that have none, such as pursuing a creative ambition, repairing a relationship or looking after one's health. Such things can be deferred indefinitely.",
   "Urban drives this home with a chart of a 90-year life rendered as weeks, a single page of little boxes. The image is meant not to induce guilt but to prompt reflection, and it leaves the audience asking which of their own monkeys deserve attention now."],
  [w("sheepish","adjective","/ˈʃiː.pɪʃ/","不好意思的","embarrassed because you did something silly","a sheepish smile","a sheepish confession 難為情的坦白。"),
   w("frenzy","noun","/ˈfren.zi/","狂熱、瘋狂狀態","a state of wild, uncontrolled activity","a frenzy of activity","in a frenzy 瘋狂地。"),
   w("nominally","adverb","/ˈnɑː.mə.nəl.i/","名義上","in name only, not in reality","nominally in charge","nominally steers 名義上掌舵。"),
   w("commandeer","verb","/ˌkɑː.mənˈdɪr/","強占、奪取","to take control of something by force","They commandeered a car.","commandeer the controls 搶走方向盤。"),
   w("loom","verb","/luːm/","逼近","to seem about to happen, often threateningly","Exams are looming.","a deadline looms 期限逼近。"),
   w("sobering","adjective","/ˈsoʊ.bɚ.ɪŋ/","發人深省的","making you serious and thoughtful","a sobering thought","a more sobering point 更嚴肅的重點。"),
   w("corrosive","adjective","/kəˈroʊ.sɪv/","有腐蝕性的、有害的","gradually causing damage","the corrosive effects of stress","truly corrosive 真正有害的。"),
   w("indefinitely","adverb","/ɪnˈdef.ən.ət.li/","無限期地","for a period with no fixed end","postponed indefinitely","be deferred indefinitely 被無限期拖延。")],
  [gr("only when 開頭的句子","Order is restored only when… 只有在…時才。","Order is restored only when the Panic Monster awakens, as a deadline looms."),
   gr("倒裝 Beneath the humor lies…","地點片語前置，動詞在主詞前。","Beneath the humor lies a more sobering point."),
   gr("not to A but to B","目的對比：不是要…而是要…。","The image is meant not to induce guilt but to prompt reflection")],
  [q("What restores order in Urban's model?","The Panic Monster","The Rational Decision-Maker alone","A teacher"),
   q("Which kind of procrastination does Urban consider most harmful?","Delaying goals that have no deadline","Delaying school essays","Delaying lunch"),
   q("What is the purpose of the life calendar?","To prompt reflection, not guilt","To schedule meetings","To scare the audience")]),
]
